import { Group, Mesh, PlaneGeometry, Vector3 } from 'three/webgpu';
import { MeshStandardNodeMaterial, uv, vec3, mix, uniform, float } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(0, 0, 0);
  root.rotation.order = 'YXZ';

  // ============================================================================
  // DESIGN TOKENS
  // ============================================================================
  const TILE_WIDTH = 1.0;
  const TILE_HEIGHT = 0.62;
  const GRID_GAP = 0.25; // 1x base unit
  const GRID_COLS = 3;
  const GRID_ROWS = 2;
  const TOTAL_GRID_WIDTH = GRID_COLS * TILE_WIDTH + (GRID_COLS - 1) * GRID_GAP; // 3.5
  const TOTAL_GRID_HEIGHT = GRID_ROWS * TILE_HEIGHT + (GRID_ROWS - 1) * GRID_GAP; // 1.49
  const KICKER_OFFSET_Y = 0.3;
  const TILE_CHAMFER = 0.02;

  const colorBkg = 0x0b0b10;
  const colorSurface = 0x16161d;
  const colorAccent = 0xff2a38;
  const colorPaper = 0xe8ecf2;
  const colorGradTop = 0x1a1a22;
  const colorGradBot = 0x121218;

  // Brand marks in display order (top-left, top-center, top-right, bottom-left, bottom-center, bottom-right)
  const brandMarks = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES',
  ];

  // ============================================================================
  // BUILD BACKDROP GRADIENT PLANE
  // ============================================================================
  const backdropGeometry = new PlaneGeometry(8, 6);
  const backdropUV = uv();
  const gradientColor = mix(
    vec3(colorGradTop >> 16, (colorGradTop >> 8) & 0xff, colorGradTop & 0xff).divideScalar(255),
    vec3(colorGradBot >> 16, (colorGradBot >> 8) & 0xff, colorGradBot & 0xff).divideScalar(255),
    backdropUV.y
  );
  const backdropMaterial = new MeshStandardNodeMaterial();
  backdropMaterial.colorNode = gradientColor;
  backdropMaterial.emissiveIntensity = 0;
  backdropMaterial.metalness = 0;
  backdropMaterial.roughness = 1;
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ============================================================================
  // BRUSHED METAL TILE MATERIAL (shared across all tiles)
  // ============================================================================
  const createTileMaterial = () => {
    const matUV = uv();
    const tileVerticalGradient = mix(
      vec3(colorGradTop >> 16, (colorGradTop >> 8) & 0xff, colorGradTop & 0xff).divideScalar(255),
      vec3(colorGradBot >> 16, (colorGradBot >> 8) & 0xff, colorGradBot & 0xff).divideScalar(255),
      matUV.y
    );

    const mat = new MeshStandardNodeMaterial();
    mat.colorNode = tileVerticalGradient;
    mat.metalness = uniform(0.5);
    mat.roughness = uniform(0.55);
    mat.emissiveIntensity = 0;

    // Anisotropy (brushed effect) — aligned to x-axis
    mat.anisotropyIntensity = uniform(0.6);
    mat.anisotropyRotation = uniform(0); // 0 rad = x-aligned

    // Clearcoat for premium finish
    mat.clearcoat = uniform(0.2);
    mat.clearcoatRoughness = uniform(0.3);

    return mat;
  };

  // ============================================================================
  // GRID CONTAINER (centered at origin)
  // ============================================================================
  const gridContainer = new Group();
  gridContainer.position.set(-TOTAL_GRID_WIDTH / 2, -TOTAL_GRID_HEIGHT / 2, 0);
  root.add(gridContainer);

  // ============================================================================
  // BUILD TILES
  // ============================================================================
  const tiles = [];
  const tileObjects = [];

  for (let row = 0; row < GRID_ROWS; row++) {
    for (let col = 0; col < GRID_COLS; col++) {
      const tileIndex = row * GRID_COLS + col;
      const brandMark = brandMarks[tileIndex] || '';

      // Position within grid
      const tileX =
        col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
      const tileY =
        row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

      // Geometry with chamfered edges (rounded corners)
      const geometry = new PlaneGeometry(TILE_WIDTH, TILE_HEIGHT, 4, 4);

      // Apply chamfer by moving corner vertices inward
      const posAttr = geometry.attributes.position;
      for (let i = 0; i < posAttr.count; i++) {
        let x = posAttr.getX(i);
        let y = posAttr.getY(i);
        const halfW = TILE_WIDTH / 2;
        const halfH = TILE_HEIGHT / 2;

        // Distance from corner (max of abs x and y in normalized space)
        const cornerDist = Math.max(
          Math.abs(x) - (halfW - TILE_CHAMFER),
          Math.abs(y) - (halfH - TILE_CHAMFER)
        );

        if (cornerDist > 0) {
          const scale = Math.max(0, 1 - cornerDist / TILE_CHAMFER);
          x *= scale + (1 - scale) * Math.sign(x);
          y *= scale + (1 - scale) * Math.sign(y);
          posAttr.setXY(i, x, y);
        }
      }
      posAttr.needsUpdate = true;

      const material = createTileMaterial();
      const tile = new Mesh(geometry, material);
      tile.position.set(tileX, tileY, 0);
      gridContainer.add(tile);

      // Store for interaction & animation
      tiles.push({
        mesh: tile,
        brandMark,
        material,
        initialZ: 0,
      });
      tileObjects.push(tile);
    }
  }

  // ============================================================================
  // RENDER BRAND MARKS AS TEXT
  // ============================================================================
  const textGroup = new Group();
  gridContainer.add(textGroup);

  for (let i = 0; i < tiles.length; i++) {
    const tile = tiles[i];
    const row = Math.floor(i / GRID_COLS);
    const col = i % GRID_COLS;

    const tileX =
      col * (TILE_WIDTH + GRID_GAP) + TILE_WIDTH / 2;
    const tileY =
      row * (TILE_HEIGHT + GRID_GAP) + TILE_HEIGHT / 2;

    // Create text mesh
    const textMesh = ctx.fontAtlas.createText(tile.brandMark, {
      fontSize: 13,
      color: colorPaper,
      align: 'center',
      letterSpacingPx: 1.04, // 0.08em at 13px = ~1.04px
    });

    textMesh.position.set(tileX, tileY, 0.01); // Slight z offset above tile
    textMesh.userData.opacity = 0.78;
    textMesh.userData.targetOpacity = 0.78;

    // Apply initial opacity
    if (textMesh.children && textMesh.children.length > 0) {
      textMesh.children.forEach((child) => {
        if (child.material) {
          child.material.opacity = 0.78;
          child.material.transparent = true;
        }
      });
    }

    textGroup.add(textMesh);
    tile.textMesh = textMesh;
  }

  // ============================================================================
  // KICKER TEXT ("AS FEATURED IN")
  // ============================================================================
  const kickerMesh = ctx.fontAtlas.createText('AS FEATURED IN', {
    fontSize: 9,
    color: colorPaper,
    align: 'center',
    letterSpacingPx: 1.08, // 0.12em at 9px = ~1.08px
  });
  kickerMesh.position.set(0, TOTAL_GRID_HEIGHT / 2 + KICKER_OFFSET_Y, 0);
  root.add(kickerMesh);

  // ============================================================================
  // ADD LIGHTING (key light rakes at 35° elevation for anisotropic sweep)
  // ============================================================================
  const { DirectionalLight, PointLight } = ctx.THREE;

  // Key light at 35° elevation, raking across tiles
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  const keyElevation = (35 * Math.PI) / 180;
  const keyAzimuth = 0; // aligned to x-axis for anisotropic sweep
  keyLight.position.set(
    Math.cos(keyAzimuth) * 5 * Math.cos(keyElevation),
    Math.sin(keyElevation) * 5,
    Math.sin(keyAzimuth) * 5 * Math.cos(keyElevation)
  );
  keyLight.target.position.set(0, 0, 0);
  root.add(keyLight);
  root.add(keyLight.target);

  // Rim light (opposite side, accent hue optional)
  const rimLight = new DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(-3, 1.5, 2);
  rimLight.target.position.set(0, 0, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  // ============================================================================
  // ENTRANCE ANIMATION (stagger-cards: fade-up + translate-y)
  // ============================================================================
  const entranceTl = gsap.timeline({ paused: false });

  // Animate tiles
  tileObjects.forEach((tile, idx) => {
    tile.position.y += 0.2; // Start 0.2 units above
    gsap.set(tile.material, { opacity: 0 });

    entranceTl.to(
      tile.position,
      {
        y: `-=0.2`,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      idx * 0.08
    );

    entranceTl.to(
      tile.material,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      idx * 0.08
    );

    // Animate text opacity in parallel
    if (tile.textMesh && tile.textMesh.children) {
      entranceTl.to(
        tile.textMesh.userData,
        {
          opacity: tile.userData.targetOpacity,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          onUpdate() {
            if (tile.textMesh.children && tile.textMesh.children.length > 0) {
              tile.textMesh.children.forEach((child) => {
                if (child.material) {
                  child.material.opacity = tile.textMesh.userData.opacity;
                }
              });
            }
          },
        },
        idx * 0.08
      );
    }
  });

  // Animate kicker
  kickerMesh.position.y += 0.2;
  gsap.set(kickerMesh.userData, { opacity: 0 });
  if (kickerMesh.children && kickerMesh.children.length > 0) {
    kickerMesh.children.forEach((child) => {
      if (child.material) {
        child.material.opacity = 0;
      }
    });
  }

  entranceTl.to(
    kickerMesh.position,
    {
      y: `-=0.2`,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );

  entranceTl.to(
    kickerMesh.userData,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate() {
        if (kickerMesh.children && kickerMesh.children.length > 0) {
          kickerMesh.children.forEach((child) => {
            if (child.material) {
              child.material.opacity = kickerMesh.userData.opacity;
            }
          });
        }
      },
    },
    0
  );

  // ============================================================================
  // HOVER INTERACTIONS (per-tile wordmark opacity + translateZ)
  // ============================================================================
  const hoverHandlers = {};

  tileObjects.forEach((tile, idx) => {
    const tileData = tiles[idx];

    // Hover enter
    hoverHandlers[`tile-${idx}-enter`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 1.0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0.05,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    // Hover exit
    hoverHandlers[`tile-${idx}-exit`] = () => {
      const textMesh = tileData.textMesh;
      if (!textMesh) return;

      gsap.to(textMesh.userData, {
        opacity: 0.78,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate() {
          if (textMesh.children && textMesh.children.length > 0) {
            textMesh.children.forEach((child) => {
              if (child.material) {
                child.material.opacity = textMesh.userData.opacity;
              }
            });
          }
        },
      });

      gsap.to(tile.position, {
        z: 0,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    // Attach to tile userData for event system
    tile.userData.tileIndex = idx;
    tile.userData.onHoverEnter = hoverHandlers[`tile-${idx}-enter`];
    tile.userData.onHoverExit = hoverHandlers[`tile-${idx}-exit`];
  });

  // ============================================================================
  // CLEANUP
  // ============================================================================
  root.userData.cleanup = () => {
    entranceTl.kill();
    gsap.globalTimeline.getChildren().forEach((tl) => {
      if (tl._targets && tl._targets.some((t) => tileObjects.includes(t))) {
        tl.kill();
      }
    });

    // Dispose geometries & materials
    backdrop.geometry.dispose();
    backdrop.material.dispose();

    tileObjects.forEach((tile) => {
      tile.geometry.dispose();
      tile.material.dispose();
    });

    textGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });

    kickerMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });

    keyLight.dispose();
    rimLight.dispose();
  };

  // ============================================================================
  // ATTACH EVENT HANDLERS
  // ============================================================================
  root.userData.handlers = hoverHandlers;

  return root;
}
